-- 0017 · tables the routes created on first use and no migration declared.
-- functions/api/operations.js built notification_prefs/deliveries,
-- accounting_documents/entries/periods, payslips, payroll_periods,
-- payment_links and payment_refunds the first time each feature ran, and
-- hotel_monthly_declarations only existed as an unapplied dated file
-- (migrations/legacy/2026-09-03-hotel-declarations.sql). None of them exists in
-- production (sqlite_master read on 26 October 2026), so this only creates
-- empty tables. The DDL is what the routes run, generated by running their
-- ensure* functions against an empty database, so a table a route already
-- created elsewhere is left as it is (IF NOT EXISTS). Once production has
-- applied 0017, MINIMUM_SCHEMA_VERSION can move to 17 and the runtime creation
-- can leave the routes (docs/ops/SCHEMA-FALLBACKS.md).

CREATE TABLE IF NOT EXISTS notification_prefs (
  merchant TEXT NOT NULL,
  kind TEXT NOT NULL,
  channels TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  updated_ts INTEGER NOT NULL,
  PRIMARY KEY (merchant, kind)
);

CREATE TABLE IF NOT EXISTS notification_deliveries (
  id TEXT PRIMARY KEY,
  merchant TEXT NOT NULL,
  command_id TEXT NOT NULL,
  dedupe_key TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL DEFAULT '',
  channel TEXT NOT NULL,
  recipient TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  created_ts INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_notify_dedupe ON notification_deliveries (merchant, dedupe_key, created_ts DESC);

CREATE INDEX IF NOT EXISTS idx_notify_command ON notification_deliveries (merchant, command_id);

CREATE TABLE IF NOT EXISTS accounting_documents (
  id TEXT PRIMARY KEY, merchant TEXT NOT NULL, kind TEXT NOT NULL,
  series TEXT NOT NULL, seq INTEGER NOT NULL, number TEXT NOT NULL,
  doc_date TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'MAD',
  total_cents INTEGER NOT NULL, tax_cents INTEGER NOT NULL DEFAULT 0,
  customer TEXT NOT NULL DEFAULT '', parent_number TEXT NOT NULL DEFAULT '',
  command_id TEXT NOT NULL DEFAULT '', created_ts INTEGER NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_acc_seq ON accounting_documents (merchant, series, seq);

CREATE UNIQUE INDEX IF NOT EXISTS idx_acc_number ON accounting_documents (merchant, number);

CREATE INDEX IF NOT EXISTS idx_acc_parent ON accounting_documents (merchant, parent_number);

CREATE TABLE IF NOT EXISTS accounting_entries (
  id TEXT PRIMARY KEY, merchant TEXT NOT NULL, document_id TEXT NOT NULL,
  number TEXT NOT NULL, doc_date TEXT NOT NULL, account TEXT NOT NULL,
  label TEXT NOT NULL DEFAULT '', debit_cents INTEGER NOT NULL DEFAULT 0,
  credit_cents INTEGER NOT NULL DEFAULT 0, created_ts INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_acc_entries_period ON accounting_entries (merchant, doc_date);

CREATE TABLE IF NOT EXISTS accounting_periods (
  merchant TEXT NOT NULL, period TEXT NOT NULL, locked_ts INTEGER NOT NULL,
  locked_by TEXT NOT NULL DEFAULT '', command_id TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (merchant, period)
);

CREATE TABLE IF NOT EXISTS payslips (
  id TEXT PRIMARY KEY, merchant TEXT NOT NULL, period TEXT NOT NULL,
  member_id TEXT NOT NULL, member_name TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT '', rate_set TEXT NOT NULL DEFAULT '',
  base_cents INTEGER NOT NULL DEFAULT 0, overtime_cents INTEGER NOT NULL DEFAULT 0,
  bonus_cents INTEGER NOT NULL DEFAULT 0, advance_cents INTEGER NOT NULL DEFAULT 0,
  gross_cents INTEGER NOT NULL, capped_cents INTEGER NOT NULL DEFAULT 0,
  cnss_cents INTEGER NOT NULL DEFAULT 0, amo_cents INTEGER NOT NULL DEFAULT 0,
  igr_cents INTEGER NOT NULL DEFAULT 0, employer_cents INTEGER NOT NULL DEFAULT 0,
  net_cents INTEGER NOT NULL, dependents INTEGER NOT NULL DEFAULT 0,
  command_id TEXT NOT NULL DEFAULT '', created_ts INTEGER NOT NULL, updated_ts INTEGER NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_payslip_member ON payslips (merchant, period, member_id);

CREATE INDEX IF NOT EXISTS idx_payslip_period ON payslips (merchant, period);

CREATE TABLE IF NOT EXISTS payroll_periods (
  merchant TEXT NOT NULL, period TEXT NOT NULL, status TEXT NOT NULL,
  employees INTEGER NOT NULL DEFAULT 0, gross_cents INTEGER NOT NULL DEFAULT 0,
  net_cents INTEGER NOT NULL DEFAULT 0, employer_cents INTEGER NOT NULL DEFAULT 0,
  journal_number TEXT NOT NULL DEFAULT '', declaration TEXT NOT NULL DEFAULT '',
  updated_ts INTEGER NOT NULL, PRIMARY KEY (merchant, period)
);

CREATE TABLE IF NOT EXISTS payment_links (
  merchant TEXT NOT NULL, reference TEXT NOT NULL, seq INTEGER NOT NULL,
  command_id TEXT NOT NULL DEFAULT '', provider_ref TEXT NOT NULL DEFAULT '',
  url TEXT NOT NULL DEFAULT '', amount_cents INTEGER NOT NULL,
  paid_cents INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'MAD',
  description TEXT NOT NULL DEFAULT '', customer TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL, created_ts INTEGER NOT NULL, updated_ts INTEGER NOT NULL,
  PRIMARY KEY (merchant, reference)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_pay_seq ON payment_links (merchant, seq);

CREATE TABLE IF NOT EXISTS payment_refunds (
  id TEXT PRIMARY KEY, merchant TEXT NOT NULL, reference TEXT NOT NULL,
  number TEXT NOT NULL, amount_cents INTEGER NOT NULL, reason TEXT NOT NULL DEFAULT '',
  command_id TEXT NOT NULL DEFAULT '', provider_ref TEXT NOT NULL DEFAULT '',
  created_ts INTEGER NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_pay_refund_number ON payment_refunds (merchant, number);

CREATE INDEX IF NOT EXISTS idx_pay_refund_ref ON payment_refunds (merchant, reference, created_ts);

-- Hotel monthly declarations and revisions ledger (append-only), from the
-- legacy dated file, unchanged. Immutability enforced by triggers.
CREATE TABLE IF NOT EXISTS hotel_monthly_declarations (
  merchant TEXT NOT NULL,
  month TEXT NOT NULL,
  revision INTEGER NOT NULL DEFAULT 1,
  state TEXT NOT NULL DEFAULT 'closed',
  source_cursor INTEGER NOT NULL DEFAULT 0,
  -- Required: every seal or rectification carries a client-generated key, so a
  -- retried request replays instead of forking the revision chain.
  idempotency_key TEXT NOT NULL,
  canonical_hash TEXT NOT NULL,
  previous_hash TEXT NOT NULL DEFAULT '',
  payload_json TEXT NOT NULL,
  lineage_json TEXT NOT NULL DEFAULT '{}',
  closed_at INTEGER NOT NULL,
  closed_by_user_id TEXT NOT NULL DEFAULT '',
  closed_by_name TEXT NOT NULL DEFAULT '',
  rectification_reason TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  PRIMARY KEY (merchant, month, revision),
  UNIQUE (merchant, idempotency_key)
);

CREATE INDEX IF NOT EXISTS idx_hotel_decl_merchant_month
  ON hotel_monthly_declarations (merchant, month, revision);

-- Triggers enforcing that finalized declaration rows are strictly immutable
CREATE TRIGGER IF NOT EXISTS prevent_declaration_update
BEFORE UPDATE ON hotel_monthly_declarations BEGIN
  SELECT RAISE(ABORT, 'hotel_monthly_declarations rows are immutable; append a new revision');
END;

CREATE TRIGGER IF NOT EXISTS prevent_declaration_delete
BEFORE DELETE ON hotel_monthly_declarations BEGIN
  SELECT RAISE(ABORT, 'hotel_monthly_declarations rows cannot be deleted');
END;
